SELECT *, LEAD(age, 2) OVER w_running AS next_age, ROW_NUMBER() OVER w_recent AS seq_no, FIRST_VALUE(segment, TRUE) OVER (PARTITION BY city, country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_segment, CUME_DIST() OVER (PARTITION BY segment, city ORDER BY age DESC NULLS FIRST) AS age_cume_dist, SUM(age) OVER (PARTITION BY country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_age FROM customers WINDOW w_running AS (PARTITION BY country ORDER BY signup_date, id), w_recent AS (PARTITION BY segment ORDER BY credit_limit DESC, id);
